 public static void main(String[] args)throws Exception{var reference=read("screenGetterQueriesReference");var source=read("screenLightQueriesReference");if(!source.get("sha256").equals(reference.get("lightSha256")))throw new AssertionError("Source light dependency");int cases=0,getters=0;var catalog=NativeScreenCatalog.INSTANCE;for(var entry:reference.getAsJsonArray("cases")){var row=entry.getAsJsonObject();var base=source.getAsJsonArray("cases").get(row.get("case").getAsInt()).getAsJsonObject();var family=ScreenFamily.fromId(base.get("id").getAsString());var tag=TagParser.parseTag(base.get("saved").getAsString());tag.putBoolean("DisplaySplit",row.get("split").getAsBoolean());tag.putBoolean("smallInput",row.get("small").getAsBoolean());var settings=NativeScreenSettings.read(tag,catalog);var d=settings.scalar();var controls=java.util.List.of(NativeScreenControls.read(tag.getCompound("RedstonePrimary"),family.standaloneControlRows(0)),NativeScreenControls.read(tag.getCompound("RedstoneSecondary"),family.standaloneControlRows(1)));var frames=FrameSettings.read(new ModernHousingTags(tag),catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);var app=NativeScreenAppearance.of(family,settings,frames,controls,7,catalog);var context=new ScreenPowerQueries.Context(family,settings.activation().data().mode,d.displayMode,d.redstoneEnabled,controls.get(0).enabled(),controls.get(1).enabled(),settings.channelLevel(),d.channelSignal,frames.split,d.smallInput,app.overrides,settings.primarySurface(),settings.secondarySurface());int[] values={Math.max(settings.channelLevel(),7),app.state,app.effectiveMode,app.primarySurface,app.secondarySurface,app.playback(0),app.playback(1),app.speed(0),app.speed(1),app.overrides?1:0,app.split?1:0,app.primaryArtwork,app.animationSpeed};for(int i=0;i<13;i++){int expected=row.getAsJsonArray("reads").get(i).getAsInt(),actual=ScreenPowerQueries.getterReads(context,i);if(actual!=expected||ScreenPowerQueries.needsPhysical(context,1<<i)!=(expected>0)||values[i]!=row.getAsJsonArray("values").get(i).getAsInt())throw new AssertionError("Source getter differs profile="+cases+" operation="+i+" reads="+actual+" expected="+expected+" value="+values[i]+" expectedValue="+row.getAsJsonArray("values").get(i));getters++;}cases++;}if(cases!=32256||getters!=419328||!reference.get("sha256").getAsString().equals("13b18754c83e1741147f020d6b663567bb973bd1721e79144a96dafd09235a42"))throw new AssertionError("Source getter coverage");System.out.println("Native Screen getter query masks PASS Source profiles="+cases+" exact values/read counts="+getters);}
 private static JsonObject read(String property)throws Exception{try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty(property)))){return JsonParser.parseReader(reader).getAsJsonObject();}}
